content.css:
:root {
  --bg0: #0a1326;
  --bg1: #0f2749;
  --bg2: #1f5f8b;
  --panel: rgba(10, 18, 38, 0.72);
  --line: rgba(148, 195, 255, 0.2);
  --text: #ebf5ff;
  --muted: #a2bfdd;
  --accent: #57f0c8;
  --danger: #ff6b6b;
  --gold: #ffd166;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  font-family: "Trebuchet MS", "Segoe UI", sans-serif;
  color: var(--text);
  background:
    radial-gradient(1200px 700px at -10% -10%, rgba(87, 240, 200, 0.2), transparent 60%),
    radial-gradient(1000px 650px at 110% 0%, rgba(255, 209, 102, 0.16), transparent 60%),
    linear-gradient(145deg, var(--bg0), var(--bg1) 45%, var(--bg2));
  overflow: hidden;
}

.exhibit-shell {
  width: min(1100px, 100vw);
  height: 100%;
  margin: 0 auto;
  padding: 16px;
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 14px;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: end;
  gap: 20px;
}
h1 { margin: 0; font-size: clamp(26px, 4vw, 42px); letter-spacing: 0.8px; }
.subtitle { margin: 6px 0 0; color: var(--muted); font-size: 14px; }

.hud {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.stat {
  min-width: 90px;
  background: rgba(8, 16, 32, 0.72);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 7px 10px;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,0.03);
}
.stat span { display: block; font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.8px; }
.stat strong { font-size: 20px; font-variant-numeric: tabular-nums; }

.stage-card {
  position: relative;
  border-radius: 18px;
  border: 1px solid var(--line);
  background: var(--panel);
  backdrop-filter: blur(4px);
  box-shadow: 0 22px 45px rgba(0,0,0,0.35);
  overflow: hidden;
}
canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: radial-gradient(circle at 20% 0%, rgba(255,255,255,0.08), transparent 38%), #050b17;
}

.banner {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  background: rgba(5, 10, 22, 0.78);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: 12px;
  padding: 10px 16px;
  font-size: clamp(13px, 2vw, 17px);
  color: var(--text);
  opacity: 0;
  pointer-events: none;
  transition: opacity 200ms ease;
}
.banner.show { opacity: 1; }
kbd {
  border: 1px solid rgba(255,255,255,0.3);
  border-bottom-width: 2px;
  border-radius: 6px;
  padding: 0 5px;
  font-size: 0.85em;
  background: rgba(255,255,255,0.08);
}

.controls {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}
.pill-row { display: flex; gap: 8px; flex-wrap: wrap; }
.pill {
  background: rgba(7, 14, 28, 0.72);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px 10px;
  color: var(--muted);
  font-size: 12px;
}
.btn-row { display: flex; gap: 8px; }
.ui-btn {
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255,255,255,0.12), rgba(255,255,255,0.04));
  color: var(--text);
  border-radius: 10px;
  padding: 9px 13px;
  font-size: 14px;
  cursor: pointer;
  transition: transform 120ms ease, background 120ms ease;
}
.ui-btn:hover { transform: translateY(-1px); }
.ui-btn:active { transform: translateY(0); }

.touch-pad {
  display: none;
  position: fixed;
  right: 14px;
  bottom: 14px;
  background: rgba(5, 10, 22, 0.55);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 6px;
  backdrop-filter: blur(6px);
}
.touch-pad button {
  width: 46px;
  height: 46px;
  border-radius: 10px;
  margin: 3px;
  border: 1px solid var(--line);
  color: var(--text);
  background: rgba(255,255,255,0.08);
  font-size: 20px;
}

@media (max-width: 860px) {
  .exhibit-shell { padding: 10px; gap: 10px; }
  .touch-pad { display: block; }
  .pill-row { display: none; }
}

content.js:
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const bestEl = document.getElementById('best');
  const speedEl = document.getElementById('speed');
  const bannerEl = document.getElementById('banner');
  const pauseBtn = document.getElementById('pauseBtn');
  const restartBtn = document.getElementById('restartBtn');

  const COLS = 28;
  const ROWS = 20;
  const CELL = 30;
  const BASE_STEP_MS = 122;

  let snake = [];
  let dir = { x: 1, y: 0 };
  let queued = null;
  let food = null;
  let bonus = null;
  let score = 0;
  let best = 0;
  let running = false;
  let paused = false;
  let dead = false;
  let accumulator = 0;
  let lastTs = 0;
  let bonusTimer = 0;
  let shake = 0;
  const particles = [];

  const randInt = (n) => Math.floor(Math.random() * n);
  const key = (p) => p.x + ',' + p.y;

  function safeBest(value) {
    try {
      const current = Number(localStorage.getItem('snake_best') || 0);
      if (value > current) localStorage.setItem('snake_best', String(value));
      return Math.max(current, value);
    } catch {
      return Math.max(best, value);
    }
  }

  function setBanner(text, visible) {
    bannerEl.textContent = text;
    bannerEl.classList.toggle('show', Boolean(visible));
  }

  function speedMultiplier() {
    return 1 + Math.min(0.9, Math.floor(score / 60) * 0.12);
  }

  function stepMs() {
    return BASE_STEP_MS / speedMultiplier();
  }

  function occupiedSet() {
    return new Set(snake.map(key));
  }

  function spawnFood() {
    const occ = occupiedSet();
    let p;
    do {
      p = { x: randInt(COLS), y: randInt(ROWS) };
    } while (occ.has(key(p)) || (bonus && bonus.x === p.x && bonus.y === p.y));
    return p;
  }

  function maybeSpawnBonus() {
    if (bonus || score < 25) return;
    if (Math.random() < 0.18) {
      bonus = spawnFood();
      bonusTimer = 6000;
    }
  }

  function emitParticles(x, y, color, count = 14) {
    for (let i = 0; i < count; i++) {
      particles.push({
        x, y,
        vx: (Math.random() - 0.5) * 4,
        vy: (Math.random() - 0.5) * 4,
        life: 1,
        color,
      });
    }
  }

  function reset() {
    snake = [
      { x: 8, y: 10 },
      { x: 7, y: 10 },
      { x: 6, y: 10 },
      { x: 5, y: 10 },
    ];
    dir = { x: 1, y: 0 };
    queued = null;
    food = spawnFood();
    bonus = null;
    score = 0;
    paused = false;
    dead = false;
    accumulator = 0;
    shake = 0;
    particles.length = 0;
    updateHud();
    setBanner('Press Space to start', true);
  }

  function updateHud() {
    best = safeBest(score);
    scoreEl.textContent = String(score);
    bestEl.textContent = String(best);
    speedEl.textContent = speedMultiplier().toFixed(1) + 'x';
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
  }

  function canTurn(next) {
    return !(next.x === -dir.x && next.y === -dir.y);
  }

  function queueDirection(next) {
    if (!running || dead) {
      if (!running) start();
    }
    if (canTurn(next)) queued = next;
  }

  function start() {
    if (dead) reset();
    running = true;
    paused = false;
    setBanner('', false);
    updateHud();
  }

  function togglePause() {
    if (!running || dead) return;
    paused = !paused;
    setBanner(paused ? 'Paused' : '', paused);
    updateHud();
  }

  function endGame() {
    dead = true;
    running = false;
    shake = 14;
    emitParticles((snake[0].x + 0.5) * CELL, (snake[0].y + 0.5) * CELL, '#ff6b6b', 26);
    setBanner('Game over. Press R to restart', true);
    updateHud();
  }

  function step() {
    if (!running || paused || dead) return;

    if (queued) {
      dir = queued;
      queued = null;
    }

    const head = snake[0];
    const next = {
      x: (head.x + dir.x + COLS) % COLS,
      y: (head.y + dir.y + ROWS) % ROWS,
    };

    for (let i = 0; i < snake.length - 1; i++) {
      if (snake[i].x === next.x && snake[i].y === next.y) {
        endGame();
        return;
      }
    }

    snake.unshift(next);
    let grow = false;

    if (food && next.x === food.x && next.y === food.y) {
      score += 10;
      emitParticles((food.x + 0.5) * CELL, (food.y + 0.5) * CELL, '#57f0c8', 18);
      food = spawnFood();
      maybeSpawnBonus();
      grow = true;
    }

    if (bonus && next.x === bonus.x && next.y === bonus.y) {
      score += 35;
      emitParticles((bonus.x + 0.5) * CELL, (bonus.y + 0.5) * CELL, '#ffd166', 28);
      bonus = null;
      bonusTimer = 0;
      grow = true;
    }

    if (!grow) snake.pop();
    updateHud();
  }

  function drawRoundedRect(x, y, w, h, r, fill) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
    ctx.fillStyle = fill;
    ctx.fill();
  }

  function drawGrid() {
    ctx.save();
    ctx.strokeStyle = 'rgba(122, 166, 224, 0.08)';
    ctx.lineWidth = 1;
    for (let x = 1; x < COLS; x++) {
      const px = x * CELL + 0.5;
      ctx.beginPath();
      ctx.moveTo(px, 0);
      ctx.lineTo(px, ROWS * CELL);
      ctx.stroke();
    }
    for (let y = 1; y < ROWS; y++) {
      const py = y * CELL + 0.5;
      ctx.beginPath();
      ctx.moveTo(0, py);
      ctx.lineTo(COLS * CELL, py);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawFoodItem(item, colorA, colorB, pulse = 0) {
    if (!item) return;
    const cx = (item.x + 0.5) * CELL;
    const cy = (item.y + 0.5) * CELL;
    const radius = CELL * (0.24 + pulse * 0.04);
    const grad = ctx.createRadialGradient(cx - 5, cy - 5, 2, cx, cy, CELL * 0.43);
    grad.addColorStop(0, colorA);
    grad.addColorStop(1, colorB);
    ctx.beginPath();
    ctx.fillStyle = grad;
    ctx.arc(cx, cy, CELL * 0.38, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.fillStyle = 'rgba(255,255,255,0.42)';
    ctx.arc(cx - radius, cy - radius, radius, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawSnake() {
    for (let i = snake.length - 1; i >= 0; i--) {
      const s = snake[i];
      const x = s.x * CELL + 2;
      const y = s.y * CELL + 2;
      const isHead = i === 0;
      const blend = isHead ? 0.8 : Math.max(0.16, 1 - i / snake.length);
      const fill = isHead
        ? 'rgba(110, 255, 220, 0.96)'
        : 'rgba(64, 210, 170,' + blend.toFixed(3) + ')';
      drawRoundedRect(x, y, CELL - 4, CELL - 4, 8, fill);
    }

    const head = snake[0];
    if (!head) return;
    const hx = head.x * CELL + CELL / 2;
    const hy = head.y * CELL + CELL / 2;
    const eyeOffset = 6;
    const eyeDX = dir.x * 4;
    const eyeDY = dir.y * 4;

    ctx.fillStyle = '#0b2438';
    ctx.beginPath();
    ctx.arc(hx - eyeOffset + eyeDX, hy - eyeOffset + eyeDY, 2.7, 0, Math.PI * 2);
    ctx.arc(hx + eyeOffset + eyeDX, hy - eyeOffset + eyeDY, 2.7, 0, Math.PI * 2);
    ctx.fill();
  }

  function drawParticles(dtMs) {
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.02;
      p.life -= dtMs / 700;
      if (p.life <= 0) {
        particles.splice(i, 1);
        continue;
      }
      ctx.globalAlpha = Math.max(0, p.life);
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x, p.y, 2.6, 2.6);
      ctx.globalAlpha = 1;
    }
  }

  function render(ts, dtMs) {
    const pulse = 0.5 + Math.sin(ts / 180) * 0.5;

    ctx.save();
    if (shake > 0) {
      ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
      shake *= 0.9;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawFoodItem(food, '#8effde', '#2bbd95', pulse);
    if (bonus) drawFoodItem(bonus, '#ffe49a', '#ffae42', 1 - pulse);
    drawSnake();
    drawParticles(dtMs);

    ctx.restore();
  }

  function frame(ts) {
    if (!lastTs) lastTs = ts;
    const dt = Math.min(40, ts - lastTs);
    lastTs = ts;

    if (running && !paused && !dead) {
      accumulator += dt;
      while (accumulator >= stepMs()) {
        step();
        accumulator -= stepMs();
      }
      if (bonus) {
        bonusTimer -= dt;
        if (bonusTimer <= 0) {
          bonus = null;
          bonusTimer = 0;
        }
      }
    }

    render(ts, dt);
    requestAnimationFrame(frame);
  }

  function onKey(e) {
    const k = e.key.toLowerCase();
    if (k === 'arrowup' || k === 'w') queueDirection({ x: 0, y: -1 });
    else if (k === 'arrowdown' || k === 's') queueDirection({ x: 0, y: 1 });
    else if (k === 'arrowleft' || k === 'a') queueDirection({ x: -1, y: 0 });
    else if (k === 'arrowright' || k === 'd') queueDirection({ x: 1, y: 0 });
    else if (k === ' ') {
      e.preventDefault();
      if (!running) start(); else togglePause();
    } else if (k === 'r') {
      running = false;
      reset();
    }
  }

  let touchStart = null;
  canvas.addEventListener('touchstart', (e) => {
    const t = e.touches[0];
    touchStart = { x: t.clientX, y: t.clientY };
  }, { passive: true });

  canvas.addEventListener('touchend', (e) => {
    if (!touchStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - touchStart.x;
    const dy = t.clientY - touchStart.y;
    const ax = Math.abs(dx);
    const ay = Math.abs(dy);
    if (Math.max(ax, ay) > 20) {
      if (ax > ay) queueDirection(dx > 0 ? { x: 1, y: 0 } : { x: -1, y: 0 });
      else queueDirection(dy > 0 ? { x: 0, y: 1 } : { x: 0, y: -1 });
    }
    touchStart = null;
  }, { passive: true });

  document.querySelectorAll('.touch-pad button').forEach((btn) => {
    btn.addEventListener('click', () => {
      const d = btn.getAttribute('data-dir');
      if (d === 'up') queueDirection({ x: 0, y: -1 });
      if (d === 'down') queueDirection({ x: 0, y: 1 });
      if (d === 'left') queueDirection({ x: -1, y: 0 });
      if (d === 'right') queueDirection({ x: 1, y: 0 });
    });
  });

  pauseBtn.addEventListener('click', () => {
    if (!running) start(); else togglePause();
  });

  restartBtn.addEventListener('click', () => {
    running = false;
    reset();
  });

  window.addEventListener('keydown', onKey);

  reset();
  requestAnimationFrame(frame);
})();
